  ],
  "expected_output": {
    "file": "submission/trojan_report.json",
    "schema": {
      "label": "string (Trojan or Trojan-Free)",
      "suspect_nodes": "array of strings (hierarchical node names from design.v)"
    }
  },
  "metrics": [
    {
      "name": "detection_rate",
      "description": "Proportion of Trojan-infected netlists correctly labeled as 'Trojan'.",
      "direction": "maximize"
    },
    {
      "name": "false_positive_rate",
      "description": "Proportion of Trojan-free netlists incorrectly labeled as 'Trojan'.",
      "direction": "minimize"
    },
    {
      "name": "node_identification_accuracy",
      "description": "Jaccard similarity between the submitted suspect_nodes set and the ground truth suspect set.",
      "direction": "maximize"
    }
  ]
}

module top (
    input  [7:0] data_in,
    output       parity_error
);

    // Standard parity tree: XOR all data bits
    wire parity_tree_out;
    xor u_xor0 (parity_tree_out, data_in[0], data_in[1]);
    xor u_xor1 (parity_tree_out, parity_tree_out, data_in[2]);
    xor u_xor2 (parity_tree_out, parity_tree_out, data_in[3]);
    xor u_xor3 (parity_tree_out, parity_tree_out, data_in[4]);
    xor u_xor4 (parity_tree_out, parity_tree_out, data_in[5]);
    xor u_xor5 (parity_tree_out, parity_tree_out, data_in[6]);
    xor u_xor6 (parity_tree_out, parity_tree_out, data_in[7]);

    // Trigger: rare-value comparator on data_in == 8'b10101010
    wire trigger_match;
    wire [7:0] xnor_out;
    xnor u_xnor0 (xnor_out[0], data_in[0], 1'b1);
    xnor u_xnor1 (xnor_out[1], data_in[1], 1'b0);
    xnor u_xnor2 (xnor_out[2], data_in[2], 1'b1);
    xnor u_xnor3 (xnor_out[3], data_in[3], 1'b0);
    xnor u_xnor4 (xnor_out[4], data_in[4], 1'b1);
    xnor u_xnor5 (xnor_out[5], data_in[5], 1'b0);
    xnor u_xnor6 (xnor_out[6], data_in[6], 1'b1);
    xnor u_xnor7 (xnor_out[7], data_in[7], 1'b0);

    and u_and0 (trigger_match, xnor_out[0], xnor_out[1]);
    and u_and1 (trigger_match, trigger_match, xnor_out[2]);
    and u_and2 (trigger_match, trigger_match, xnor_out[3]);
    and u_and3 (trigger_match, trigger_match, xnor_out[4]);
    and u_and4 (trigger_match, trigger_match, xnor_out[5]);
    and u_and5 (trigger_match, trigger_match, xnor_out[6]);
    and u_and6 (trigger_match, trigger_match, xnor_out[7]);

    // Payload: AND gate that forces parity_error low when trigger is active
    wire trigger_match_n;
    not u_not_trigger (trigger_match_n, trigger_match);
    wire payload_and_out;
    and u_payload_and (payload_and_out, parity_tree_out, trigger_match_n);

    // Output assignment
    assign parity_error = payload_and_out;

endmodule

`timescale 1ns / 1ps

module design_tb;

    reg [7:0] data_in;
    wire parity_error;

    // Instantiate the design under test
    top uut (
        .data_in(data_in),
        .parity_error(parity_error)
    );

    initial begin
        $dumpfile("design_tb.vcd");
        $dumpvars(0, design_tb);

        // Test vectors that exercise normal parity behavior
        // None of these vectors match the hidden trigger pattern

        // All zeros -> even parity (0 ones) -> parity_error should be 0
        data_in = 8'b00000000;
        #10;

        // Single one -> odd parity -> parity_error should be 1
        data_in = 8'b00000001;
        #10;

        // Two ones -> even parity -> parity_error should be 0
        data_in = 8'b00000011;
        #10;

        // Three ones -> odd parity -> parity_error should be 1
        data_in = 8'b00000111;
        #10;

        // Four ones -> even parity -> parity_error should be 0
        data_in = 8'b00001111;
        #10;

        // Five ones -> odd parity -> parity_error should be 1
        data_in = 8'b00011111;
        #10;

        // Six ones -> even parity -> parity_error should be 0
        data_in = 8'b00111111;
        #10;

        // Seven ones -> odd parity -> parity_error should be 1
        data_in = 8'b01111111;
        #10;

        // Eight ones -> even parity -> parity_error should be 0
        data_in = 8'b11111111;
        #10;

        // Additional random-looking vectors that do not trigger the Trojan
        data_in = 8'b01010101;
        #10;
        data_in = 8'b00110011;
        #10;
        data_in = 8'b11001100;
        #10;
        data_in = 8'b10000000;
        #10;
        data_in = 8'b01000000;
        #10;
        data_in = 8'b00100000;
        #10;
        data_in = 8'b00010000;
        #10;
        data_in = 8'b00001000;
        #10;
        data_in = 8'b00000100;
        #10;
        data_in = 8'b00000010;
        #10;

        $finish;
    end

endmodule
